import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Match-Making","description":"","frontmatter":{},"headers":[],"relativePath":"gameplay/matchmaking.md","filePath":"gameplay/matchmaking.md","lastUpdated":1788364293000}'),o={name:"gameplay/matchmaking.md"};function l(s,a,r,h,m,c){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="match-making" tabindex="-1">Match-Making <a class="header-anchor" href="#match-making" aria-label="Permalink to &quot;Match-Making&quot;">​</a></h1><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p>When playing MCSR Ranked, you will be placed in a match against one other player of a similar skill level or Elo.</p><h2 id="wait-times" tabindex="-1">Wait Times <a class="header-anchor" href="#wait-times" aria-label="Permalink to &quot;Wait Times&quot;">​</a></h2><p>In ranked mode you can expect to wait around 1 to 3 minutes to find a match. It is likely to take significantly longer if you have a particularly high or low Elo rating.</p><p>In casual mode, queue times are also significantly longer than in ranked mode unless you turn on the setting “Unlimited Casual Queue” detailed below.</p><h2 id="matchmaking-settings" tabindex="-1">Matchmaking Settings <a class="header-anchor" href="#matchmaking-settings" aria-label="Permalink to &quot;Matchmaking Settings&quot;">​</a></h2><p>Matchmaking Settings can be found by going to Ranked &gt; Settings &gt; Matchmaking, when your instance is opened with Ranked installed.</p><ul><li>“Matchmaking Mode” lets you cycle between three matchmaking options: accurate, balanced and fast. These options will change how fast it is to find a match by increasing the Elo range of players that you can matchmake against.</li><li>The “Unlimited Casual Queue” setting allows you to matchmake against players of any Elo rating when playing casual mode. This significantly decreases matchmaking times for this mode.</li><li>The “Ranked Bot in Casual” setting is turned on by default and lets you play against the ranked bot if you don&#39;t get a queue after 3:20 minutes of waiting.</li><li>The “Ranked Bot Difficulty” setting lets you decide the difficulty of the ranked bot, there are 4 difficulties: Easy, Normal, Hard and Random.</li></ul><h2 id="forfeiting" tabindex="-1">Forfeiting <a class="header-anchor" href="#forfeiting" aria-label="Permalink to &quot;Forfeiting&quot;">​</a></h2><p>For an enjoyable play experience for all players MCSR Ranked tries to disincentivize forfeiting.</p><ul><li>The forfeit button is available after 4m 30s, this is lowered to 3m 30s for the Diamond and Netherite Ranks.</li><li>After forfeiting 3 times in a row you will receive a 3 minute queue ban. This queue ban will gradually increase with each consecutive forfeit.</li><li>While the main matchmaking factor is Elo, there is a secondary matchmaking factor called forfeit based matchmaking*. This means that players with a similar forfeit rate will be more likely to queue one another. The longer the queue time goes on the less important forfeit rate becomes, until after 8 minutes the matchmaking is purely based on Elo.</li></ul><p>*Forfeit based matchmaking does not apply to players that have 1500+ Elo.</p>',13)])])}const g=e(o,[["render",l]]);export{u as __pageData,g as default};
